-- Gold Query
SELECT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.potential = '61' ORDER BY t2.balance DESC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 1;

/*
Gold Result:
('Jessica Callahan',)
*/

-- Prediction Query
SELECT DISTINCT P.player_name FROM Player AS P INNER JOIN Player_Attributes AS PA ON P.player_api_id = PA.player_api_id WHERE PA.potential = 61 AND PA.balance = (SELECT MAX(balance) FROM Player_Attributes);

